<?php
declare(strict_types=1);
return static function(PDO $pdo):void{
$pdo->exec("CREATE TABLE IF NOT EXISTS reading_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,classroom_id BIGINT UNSIGNED NOT NULL,member_id BIGINT UNSIGNED NOT NULL,lesson_plan_id BIGINT UNSIGNED NOT NULL,level ENUM('basic','intermediate','advanced') NOT NULL,total_questions SMALLINT UNSIGNED NOT NULL DEFAULT 20,current_position SMALLINT UNSIGNED NOT NULL DEFAULT 0,score SMALLINT UNSIGNED NOT NULL DEFAULT 0,snapshot_json JSON NOT NULL,question_started_at DATETIME NULL,status ENUM('active','completed') NOT NULL DEFAULT 'active',started_at DATETIME NOT NULL,completed_at DATETIME NULL,KEY idx_reading_member(member_id,status,started_at),CONSTRAINT fk_rs_classroom FOREIGN KEY(classroom_id) REFERENCES classrooms(id) ON DELETE CASCADE,CONSTRAINT fk_rs_member FOREIGN KEY(member_id) REFERENCES classroom_members(id) ON DELETE CASCADE,CONSTRAINT fk_rs_plan FOREIGN KEY(lesson_plan_id) REFERENCES classroom_lesson_plans(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$pdo->exec("CREATE TABLE IF NOT EXISTS reading_attempts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reading_session_id BIGINT UNSIGNED NOT NULL,passage_id BIGINT UNSIGNED NOT NULL,question_id VARCHAR(80) NOT NULL,option_order_json JSON NOT NULL,selected_option_id VARCHAR(80) NULL,result ENUM('correct','incorrect','timed_out') NOT NULL,response_ms INT UNSIGNED NOT NULL DEFAULT 0,score SMALLINT UNSIGNED NOT NULL DEFAULT 0,answered_at DATETIME NOT NULL,UNIQUE KEY uq_reading_answer(reading_session_id,question_id),KEY idx_reading_history(passage_id,question_id,answered_at),CONSTRAINT fk_ra_session FOREIGN KEY(reading_session_id) REFERENCES reading_sessions(id) ON DELETE CASCADE,CONSTRAINT fk_ra_passage FOREIGN KEY(passage_id) REFERENCES learning_activities(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
};
